import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.BN3Eol-0.js";const g=JSON.parse('{"title":"UXD-005 — No staging: GitHub Pages serves only the docs, releases are verified on prod","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-005-no-staging-verify-on-prod.md","filePath":"uxs/decisions/UXD-005-no-staging-verify-on-prod.md"}'),i={name:"uxs/decisions/UXD-005-no-staging-verify-on-prod.md"};function s(n,e,d,c,l,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="uxd-005-—-no-staging-github-pages-serves-only-the-docs-releases-are-verified-on-prod" tabindex="-1">UXD-005 — No staging: GitHub Pages serves only the docs, releases are verified on prod <a class="header-anchor" href="#uxd-005-—-no-staging-github-pages-serves-only-the-docs-releases-are-verified-on-prod" aria-label="Permalink to &quot;UXD-005 — No staging: GitHub Pages serves only the docs, releases are verified on prod&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted</li><li><strong>Date</strong>: 2026-11-10 (decided) · 2026-11-11 (gh-pages history and follow-ups decided)</li><li><strong>Decider</strong>: the operator — &quot;Main work — no staging (operator, 2026-11-10): GitHub Pages serves only the project docs; every release goes straight to prod, validated there&quot; (<code>docs/wip/2026-11-11-0.9.9-plan.md</code> lines 16–18); ADR-097 status line &quot;Accepted · 2026-11-10 (operator)&quot;; &quot;DECIDED (operator 2026-11-11): no history rewrite&quot; (plan line 24)</li><li><strong>Answers</strong>: none from the feedback list; a process and release decision that changes what a reviewer looks at</li><li><strong>Changes</strong>: AGENTS.md (lines 91, 959), <code>CLAUDE.md</code> (line 89), <code>docs/ops/*</code>, <code>docs/guides/*</code> that named staging. The architecture is <a href="./../../adr/ADR-097">ADR-097</a>; this record keeps only the consequence for UX review.</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Staging was the app bundle on GitHub Pages, a different host from prod: no nginx headers or CSP, a <code>/orrery/</code> base path, no <code>/data</code> overlay. Its smoke &quot;could pass while prod broke&quot; and the copy was a divergent SEO-duplicate mirror (ADR-097 Context). Every release already needed <code>validate-prod</code> on the real host.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><p>ADR-097 records the alternatives. Not repeated here.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>There is <strong>no staging tier</strong>. The release flow is merge to <code>main</code>, the manual prod deploy (<code>gh workflow run &quot;Deploy to prod VPS (orrery)&quot; --ref main</code>, for a commit whose CI and docker-e2e are green), then validate-prod. <strong>GitHub Pages serves only the docs.</strong></p><p><strong>For UX review.</strong> The operator said on 2026-10-17 that green workflows check generic health, not the specific changes shipped: &quot;validate the things we did actually work with the deploy&quot; (operator note <code>validate-staging-before-prod</code>, which says this earlier rule &quot;still holds in spirit&quot; after the staging removal). Practice since 0.9.9, recorded in that note and not a separate decision: after the prod deploy, each change in the release is driven on <code>https://www.orrerylearn.com</code> and reported pass or fail with evidence per item; the local release gate (full e2e on all three Playwright projects, <code>preflight:coverage</code>, <code>build:mobile</code>) carries the weight staging used to.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Done on the branch (git log of <code>tech-debt/0.9.9</code>: <code>5c1c30f5cd6</code>, <code>9a0a803c341</code>, <code>e910a6624cd</code>, <code>74b8206f154</code>): staging workflows deleted, <code>src/lib/target-env.ts</code> removed, docs updated. Remaining and tracked in the 0.9.9 plan, not UX: the <code>deploy-prod.yml</code> patch (the operator applies it, item 1.6) and the staging leftovers on the observability side after the 0.9.9 deploy (plan section 3).</li><li>A bad commit is found on prod, not before it; the mitigation is the green-CI rule, validate-prod after the deploy, and the rollback in <code>docs/ops/deploy-prod-vps.md</code> (ADR-097 Consequences).</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p><code>.github/workflows/staging.yml</code> and <code>src/lib/target-env.ts</code> are absent in the working tree at <code>9fdf4cc4a6b</code>. The flow is not enforced by a test.</p>',13)])])}const u=o(i,[["render",s]]);export{g as __pageData,u as default};
